#!/usr/bin/env python3
"""Build one audited, dependency-free dashboard. Legacy artifacts stay in Git."""
import html, json
from pathlib import Path
R=Path(__file__).resolve().parent.parent; P=R/'pages'; P.mkdir(exist_ok=True)
def read(p): return json.loads((R/p).read_text())
s=read('data/audit-snapshot.json'); flags=read('data/flagged.json')['items']; src=read('data/sources.json')['sources']; inv=read('analysis/audit-inventory.json')['rows']; audit=read('analysis/repo-audit.json'); lines=read('analysis/model-lines.json'); corr=read('analysis/correlations.json'); strategies=read('analysis/strategies.json')['strategies']; board=read('analysis/leaderboard.json'); gates=read('analysis/validation-gates.json')['gates']; sugg=read('data/suggestions.json')['suggestions']; dec=read('data/decisions.json')['questions']
SNAP_DISPLAY=s['as_of'][8:10]+' NOV '+s['as_of'][0:4]
WEEK='WEEK 10'
def e(x): return html.escape(str(x)) if x is not None else ''
def a(u,label='Official source'): return f'<a href="{e(u)}" target="_blank" rel="noopener noreferrer">{e(label)} ↗</a>'
def b(t): return '<span class="badge '+('good' if t=='VERIFIED' else 'warn' if 'UNVERIFIED' in t or 'BLOCKED' in t else 'neutral')+'">'+e(t)+'</span>'
def table(headers,rows,caption):
 out='<div class="table-tools"><label>Filter rows <input type="search" placeholder="Search this table…" aria-label="Filter '+e(caption)+'"></label><span class="row-count">'+str(len(rows))+' rows</span></div><div class="table-wrap"><table><caption>'+e(caption)+'</caption><thead><tr>'+''.join('<th scope="col">'+e(h)+'</th>' for h in headers)+'</tr></thead><tbody>'
 for row in rows:
  out+='<tr>'+''.join('<td'+(' class="missing" aria-label="Unverified or not available"' if c is None else '')+'>'+('' if c is None else str(c) if isinstance(c,str) and c.startswith('<') else e(c))+'</td>' for c in row)+'</tr>'
 return out+'</tbody></table></div><p class="table-note">Empty cells are intentionally blank: unavailable or unverified. Links on unverified rows are verification targets, not proof.</p>'
NAV=[('index','Overview','01'),('executive-summary','Executive summary','02'),('standings','Team standings','03'),('schedule','Schedule & scores','04'),('model-lines','Line origination','05'),('strategies','Strategy library','06'),('correlations','Correlations','07'),('leaderboard','Skill leaderboard','08'),('validation-gates','Validation gates','09'),('injuries','Availability & news','10'),('player-stats','Data inventory','11'),('methodology','Methodology','12'),('repo-review','Repository audit','13'),('sources','Source register','14'),('flagged','Flagged for Review','15'),('suggestions','Suggestions','16'),('decisions','Decision framework','17'),('responsible-gambling','Responsible research','18')]
def wrap(slug,title,desc,body):
 root=slug=='index'; pre='' if root else '../'
 nav=''.join(f'<a {"aria-current=page" if key==slug else ""} href="{pre+"index.html" if key=="index" else ("pages/" if root else "")+key+".html"}"><span>{n}</span>{label}</a>' for key,label,n in NAV)
 nav += f'<a href="{pre}requirements/index.html"><span>★</span>Requirements &amp; decision review</a>'
 nav += f'<a href="{pre}strict/site/index.html"><span>↗</span>Independent evidence lab</a>'
 nav += f'<a href="{pre}decision/site/index.html"><span>↗</span>Decision support (parallel session)</a>'
 nav += f'<a href="{pre}desk/index.html"><span>↗</span>Independent desk (parallel session)</a>'
 nav += f'<a href="{pre}origination/index.html"><span>↗</span>Origination lab</a>'
 nav += f'<a href="{pre}hub/index.html"><span>↗</span>NFL hub (parallel session)</a>'
 nav += f'<a href="{pre}review/index.html"><span>↗</span>Repo review (parallel session)</a>'
 nav += f'<a href="{pre}suggestions/index.html"><span>↗</span>Suggestions register (parallel session)</a>'
 nav += f'<a href="{pre}docs/evidence-lab/index.html"><span>↗</span>Evidence lab (mirror)</a>'
 nav += f'<a href="{pre}integration/index.html"><span>★</span>Integration &amp; freshness</a>'
 return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="description" content="{e(desc)}"><title>{e(title)} · Own8</title><link rel="stylesheet" href="{pre}assets/style.css"><script src="{pre}assets/app.js" defer></script></head><body><a class="skip" href="#main">Skip to content</a><aside><a class="brand" href="{pre}index.html"><span class="brand-mark">8</span> OWN8<span class="lab">RESEARCH LAB</span></a><div class="nav-label">NFL / RESEARCH WORKSPACE</div><nav aria-label="Main navigation">{nav}</nav><div class="aside-foot"><span class="pulse"></span> Official-source audit<br><small>Snapshot · {SNAP_DISPLAY}<br>Paper research only</small></div></aside><div class="workspace"><header><span>NFL LINE ORIGINATION <span class="muted">/ {e(title)}</span></span><span class="date">2026 SEASON · {WEEK}</span></header><main id="main"><div class="eyebrow">OWN8 INTELLIGENCE / {s['as_of']}</div><h1>{e(title)}</h1><p class="lead">{e(desc)}</p>{body}</main><footer><span>OWN8 · Evidence before edge.</span><span>Snapshot, not live odds. No wagering or cash rewards.</span></footer></div></body></html>'''
def page(slug,title,desc,body): (R/'index.html' if slug=='index' else P/(slug+'.html')).write_text(wrap(slug,title,desc,body))
def note(t): return '<div class="notice"><strong>Research boundary</strong><p>'+e(t)+'</p></div>'
def sec(t): return '<h2>'+e(t)+'</h2>'
